import { atom, read, update } from 'claude-code'
import type { Register, AgentStatus } from 'claude-code'

import type { Item, ItemStatus } from '../types'

const PANE = 'task-board'
const todos = atom({ plugin: 'task-board', key: 'todos' } as const, [])
const tasks = atom({ plugin: 'task-board', key: 'tasks' } as const, [])
const agents = atom({ plugin: 'task-board', key: 'agents' } as const, [])

const fromTodo = (s: string): ItemStatus =>
  s === 'completed' ? 'done' : s === 'in_progress' ? 'running' : 'pending'

const fromAgent = (s: AgentStatus): ItemStatus =>
  s === 'completed' || s === 'idle' ? 'done'
    : s === 'failed' || s === 'killed' ? 'failed'
      : s === 'pending' ? 'pending' : 'running'

const ICON: Record<ItemStatus, string> = { pending: '○', running: '◐', done: '●', failed: '✗' }
const COLOR: Record<ItemStatus, string> = { pending: 'gray', running: 'yellow', done: 'green', failed: 'red' }

const elapsed = (it: Item, now: number) => {
  if (!it.started) return ''
  const s = Math.round(((it.ended ?? now) - it.started) / 1000)
  return s < 60 ? `${s}s` : `${Math.floor(s / 60)}m${String(s % 60).padStart(2, '0')}s`
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'tasks', description: 'Show all todos, tasks and subagents in a side panel' })
    void $.ui.open({ id: PANE, title: 'Tasks' })

    // Subagents (incl. background ones) are polled so their status stays live.
    $.clock.every(2000, async () => {
      const list = await $.agent.list()
      const now = await $.clock.now()
      await update($, agents, prev =>
        list.map(a => {
          const old = prev.find(p => p.id === a.id)
          const status = fromAgent(a.status)
          const started = old?.started ?? now
          const ended = status === 'done' || status === 'failed' ? (old?.ended ?? now) : undefined
          return { id: a.id, kind: 'agent', title: `${a.description} (${a.type})`, status, started, ended }
        }),
      )
    })

    return next(e)
  })

  on('command.run', { command: 'tasks' }, async $ => {
    await $.ui.open({ id: PANE, title: 'Tasks' })
    return { text: 'Task board opened.' }
  })

  on('tool.call', { tool: 'TodoWrite' }, async ($, e, next) => {
    const ran = await next(e)
    if (e.tool === 'TodoWrite' && !('deny' in ran && ran.deny)) {
      const now = await $.clock.now()
      await update($, todos, prev =>
        e.todos.map((t, i) => {
          const old = prev.find(p => p.title === t.content)
          const status = fromTodo(t.status)
          const started = old?.started ?? (status !== 'pending' ? now : undefined)
          const ended = status === 'done' ? (old?.ended ?? now) : undefined
          return { id: `todo-${i}`, kind: 'todo', title: t.content, status, started, ended }
        }),
      )
    }
    return ran
  })

  on('tool.call', { tool: 'TaskCreate' }, async ($, e, next) => {
    const ran = await next(e)
    if (e.tool === 'TaskCreate' && ran.result && !ran.isError) {
      const task = ran.result.task
      await update($, tasks, prev => [...prev, { id: task.id, kind: 'task', title: task.subject, status: 'pending' } satisfies Item])
    }
    return ran
  })

  on('tool.call', { tool: 'TaskUpdate' }, async ($, e, next) => {
    const ran = await next(e)
    if (e.tool === 'TaskUpdate' && ran.result && !ran.isError) {
      const now = await $.clock.now()
      await update($, tasks, prev =>
        e.status === 'deleted'
          ? prev.filter(t => t.id !== e.taskId)
          : prev.map(t => {
              if (t.id !== e.taskId) return t
              const status = e.status ? fromTodo(e.status) : t.status
              return {
                ...t,
                title: e.subject ?? t.title,
                status,
                started: t.started ?? (status !== 'pending' ? now : undefined),
                ended: status === 'done' ? (t.ended ?? now) : undefined,
              }
            }),
      )
    }
    return ran
  })

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    const { Box, Text } = $.ui.resolve(e)
    const now = await $.clock.now()
    const groups: [string, Item[]][] = [
      ['Todos', await read($, todos)],
      ['Tasks', await read($, tasks)],
      ['Subagents', await read($, agents)],
    ]
    const all = groups.flatMap(([, items]) => items)
    const done = all.filter(i => i.status === 'done').length
    const width = 20
    const filled = all.length ? Math.round((done / all.length) * width) : 0

    return (
      <Box flexDirection="column">
        {all.length === 0 ? (
          <Text dimColor>No tasks yet.</Text>
        ) : (
          <Text>
            {'█'.repeat(filled)}{'░'.repeat(width - filled)} {done}/{all.length}
          </Text>
        )}
        {groups
          .filter(([, items]) => items.length > 0)
          .map(([name, items]) => (
            <Box flexDirection="column" marginTop={1}>
              <Text bold>
                {name} ({items.filter(i => i.status === 'done').length}/{items.length})
              </Text>
              {items.map(it => (
                <Text wrap="truncate-end" dimColor={it.status === 'done'}>
                  <Text color={COLOR[it.status]}>{ICON[it.status]}</Text> {it.title}
                  {it.started ? <Text dimColor> {elapsed(it, now)}</Text> : null}
                </Text>
              ))}
            </Box>
          ))}
      </Box>
    )
  })
}

