export type ItemStatus = 'pending' | 'running' | 'done' | 'failed'
export type Item = { id: string; kind: 'todo' | 'task' | 'agent'; title: string; status: ItemStatus; started?: number; ended?: number }

declare module 'claude-code' {
  interface PluginState {
    'task-board': { todos: Item[]; tasks: Item[]; agents: Item[] }
  }
}
